   "waapi": "const parts = [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)].map(s => s.segment);\n// '👨‍👩‍👧'.length === 8、[...'👨‍👩‍👧'].length === 5、parts.length === 1\nspans.forEach((s, i) => s.animate([{ transform: 'scale(0)' }, { transform: 'scale(1.12)', offset: .7 }, { transform: 'scale(1)' }],\n  { duration: 450, delay: i * 40, easing: 'ease-out', fill: 'both' }));",
   "css": ".g { display:inline-block; transform:scale(0); animation: pop .45s cubic-bezier(.34,1.56,.64,1) forwards;\n  animation-delay: calc(var(--i) * 40ms); }\n@keyframes pop { to { transform:scale(1); } }\n@media (prefers-reduced-motion: reduce) { .g { animation:none; transform:none; } }"
