  "recipes": {
   "motion": "import { AnimatePresence, motion } from 'motion/react';\nfunction FlipWords({ words, duration = 3000 }) {\n  const [i, setI] = useState(0);\n  useEffect(() => { const id = setTimeout(() => setI((i + 1) % words.length), duration); return () => clearTimeout(id); }, [i]);\n  return (<AnimatePresence>\n    <motion.span key={words[i]} style={{ display: 'inline-block', position: 'relative' }}\n      initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}\n      transition={{ type: 'spring', stiffness: 100, damping: 10 }}\n      exit={{ opacity: 0, y: -40, x: 40, filter: 'blur(8px)', scale: 2, position: 'absolute' }}>\n      {words[i].split(' ').map((w, wi) => (\n        <span key={wi} style={{ display: 'inline-block', whiteSpace: 'nowrap' }}>\n          {[...w].map((c, ci) => (\n            <motion.span key={ci} style={{ display: 'inline-block' }}\n              initial={{ opacity: 0, y: 10, filter: 'blur(8px)' }} animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }}\n              transition={{ delay: wi * .3 + ci * .05, duration: .2 }}>{c}</motion.span>))}\n          &nbsp;\n        </span>))}\n    </motion.span>\n  </AnimatePresence>);\n}",
   "css": ".flip-out { animation: flipOut .45s cubic-bezier(.33,1,.68,1) forwards; position:absolute; }\n@keyframes flipOut { to { opacity:0; transform: translate(40px,-40px) scale(2); filter: blur(8px); } }\n.flip-in .ch { display:inline-block; animation: focusIn .2s ease-out both; animation-delay: calc(var(--i) * 50ms); }\n@keyframes focusIn { from { opacity:0; transform: translateY(10px); filter: blur(8px); } }\n@media (prefers-reduced-motion: reduce) { .flip-out, .flip-in .ch { animation-duration:1ms; } }"
  },
  "sources": [
   "https://ui.aceternity.com/components/flip-words"
  ],
