   "motion": "// Motion+의 Typewriter(React)\nimport { Typewriter } from 'motion-plus/react';\n<Typewriter as=\"p\" speed=\"fast\" variance={0.5} backspace=\"word\">{text}</Typewriter>",
   "waapi": "// 순수 JS: 간격을 시드 포함 난수로 흔들고 문장부호 뒤에 쉼을 둔다\nfunction mulberry32(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a);\n  t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }\nasync function humanType(el, text, base = 85, variance = 0.5) {\n  const r = mulberry32(42), chars = Array.from(text);\n  el.setAttribute('aria-label', text);\n  for (let i = 0; i < chars.length; i++) {\n    el.textContent = chars.slice(0, i + 1).join('');\n    let ms = base * (1 + variance * (r() * 2 - 1));\n    if (/[、。,.!?…]/.test(chars[i]) && !/[、。,.!?…]/.test(chars[i + 1] || '')) ms += 320;\n    await new Promise(res => setTimeout(res, ms));\n  }\n}",
   "css": "/* 타이핑 처리는 JS. CSS는 캐럿과 reduced-motion만 담당 */\n.human::after { content: '|'; animation: blink 1s steps(1) infinite; }\n@keyframes blink { 50% { opacity: 0; } }\n@media (prefers-reduced-motion: reduce) { .human::after { display: none; } }"
