  "recipes": {
   "svg": "<!-- 필순대로 나열한 한 줄 패스. 굵은 선으로 채움 글자를 마스크한다 -->\n<svg viewBox=\"0 0 400 120\" role=\"img\" aria-label=\"Thank you\">\n  <mask id=\"m\"><g fill=\"none\" stroke=\"#fff\" stroke-width=\"14\" stroke-linecap=\"round\">\n    <path class=\"s\" pathLength=\"1\" style=\"--d:.6s; --at:0s\" d=\"M20,90 C40,20 …\"/>\n    <path class=\"s\" pathLength=\"1\" style=\"--d:.3s; --at:.6s\" d=\"…\"/>\n  </g></mask>\n  <text x=\"20\" y=\"90\" font-family=\"'Dancing Script'\" font-size=\"80\" mask=\"url(#m)\">Thank you</text>\n</svg>",
   "css": ".s { stroke-dasharray: 1; stroke-dashoffset: 1;\n  animation: write var(--d) ease-in-out var(--at) forwards; }  /* --d는 패스 길이에 비례시킨다 */\n@keyframes write { to { stroke-dashoffset: 0; } }\n@media (prefers-reduced-motion: reduce) { .s { animation: none; stroke-dashoffset: 0; } }",
   "gsap": "// 길이에 비례한 duration으로 순서대로\nconst paths = gsap.utils.toArray('.s');\nconst tl = gsap.timeline();\npaths.forEach(p => {\n  const len = p.getTotalLength();\n  tl.fromTo(p, { strokeDasharray: len, strokeDashoffset: len }, { strokeDashoffset: 0, duration: len / 400, ease: 'sine.inOut' });\n});"
  },
