   "css": "/* <h1 aria-label=\"Stagger Up\"><span class=\"line\" aria-hidden=\"true\"><span style=\"--i:0\">S</span>…</span></h1> */\n.line { display: inline-block; overflow: clip; }\n.line span { display: inline-block; translate: 0 100%;\n  animation: up .5s cubic-bezier(.215,.61,.355,1) forwards; animation-delay: calc(var(--i) * 14ms); }\n@keyframes up { to { translate: 0 0; } }\n@media (prefers-reduced-motion: reduce) { .line span { animation: none; translate: none; } }",
