   "css": "/* 다음 장면에 별 모양 마스크를 씌워 확대 */\n.next { position: absolute; inset: 0;\n  -webkit-mask: url(star.svg) center / 0% no-repeat; mask: url(star.svg) center / 0% no-repeat;\n  animation: grow .6s cubic-bezier(.55,0,1,.45) forwards; }\n@keyframes grow { to { -webkit-mask-size: 3000%; mask-size: 3000%; } }\n@media (prefers-reduced-motion: reduce) { .next { animation: none; -webkit-mask: none; mask: none; } }",
