   "waapi": "// @property로 등록돼 있다면 WAAPI에서도 각도가 보간된다\nCSS.registerProperty?.({ name: '--angle', syntax: '<angle>', inherits: false, initialValue: '0deg' });\ndocument.querySelector('.spin').animate({ '--angle': ['0deg', '360deg'] }, { duration: 4000, iterations: Infinity, easing: 'linear' });",
