   "css": "/* 각 글자에 --i를 부여:<span style=\"--i:0\">아</span>… */\n@property --h { syntax: '<number>'; inherits: true; initial-value: 0; }\n.rainbow { animation: hue 4s linear infinite; }\n.rainbow span { color: oklch(78% .16 calc((var(--i) * 20 + var(--h)) * 1deg)); }\n@keyframes hue { to { --h: 360; } }\n@media (prefers-reduced-motion: reduce) { .rainbow { animation: none; } }",
