   "css": ".neon { color: #fff4fb;\n  text-shadow: 0 0 4px #fff, 0 0 11px #ff725e, 0 0 19px #ff725e, 0 0 40px #ff725e;\n  animation: flicker .9s linear both; }\n@keyframes flicker {\n  0%, 18%, 22%, 55%, 62%, 100% { opacity: 1; }\n  20% { opacity: .2; text-shadow: none; }\n  58% { opacity: .5; text-shadow: none; }\n}\n@media (prefers-reduced-motion: reduce) { .neon { animation: none; } }",
