  "motionDuration": 900,
  "easing": "ease-in-out",
  "feelings": [
   "부드러움",
   "무거움"
  ],
  "usages": [
   "텍스트",
   "로고"
  ],
  "description": "자간을 좁히거나 넓혀 겹친 글자끼리 곱셈이나 스크린으로 섞여, 교차 부분에 새로운 색이 생긴다.",
  "descriptionEn": "Tracking tightens (and letters scale up) until characters overlap, and the overlaps blend by screen or multiply into new colours.",
  "focus": "자간을 −0.3em까지 좁히면 옆 글자에 파고든다. 3색 글자를 스크린으로 합성하므로 겹친 부분에서만 밝은 혼색이 생긴다.",
  "focusEn": "Tightening tracking to −0.3em pushes each letter into its neighbour; with three colours combined by screen, only the overlaps glow with a new mixed colour.",
  "caution": "어두운 배경에서는 스크린(밝아짐), 밝은 배경에서는 곱하기(어두워짐)를 고른다. 겹침이 크면 글자를 구별할 수 없으므로 마지막엔 읽을 수 있는 자간으로 되돌리거나 짧은 단어에만 쓴다.",
  "cautionEn": "Use screen on dark backgrounds and multiply on light ones. Heavy overlap destroys legibility — return to readable tracking afterwards or keep it to short words.",
  "tips": [],
  "tipsEn": [],
  "recipe": "트래킹 0 → −30(AE) / 자간 0 → −0.3em / 스크린 / 곱셈 / 글자 간 블렌드",
  "recipeEn": "tracking 0 → −30 (AE) / letter-spacing 0 → −0.3em / screen / multiply / inter-character blending",
  "curve": "standard",
  "trigger": "시간·상태 변화",
  "triggerEn": "Time or state change",
  "tech": [
   "CSS",
   "AE"
  ],
  "cost": "가벼움",
  "costEn": "Light",
  "inputs": [
   "자동"
  ],
  "inputsEn": [
   "Automatic"
  ],
  "reduced": "동작을 멈추고 글자가 읽히는 대표 컷을 표시합니다.",
  "reducedEn": "Stop the motion and show a representative frame where the text is readable.",
