  "recipes": {
   "canvas": "// 저해상도로 그려 밝기를 글자로\nconst CS = ' .:-=+*#%@', cols = 64, rows = 28;\nconst sm = document.createElement('canvas'); sm.width = cols; sm.height = rows;\nconst sg = sm.getContext('2d', { willReadFrequently: true });\nfunction frame(t) {\n  sg.clearRect(0, 0, cols, rows);\n  for (let r = 0; r < rows; r++)        // 행마다 파도로 어긋나게 해 축소 전사\n    sg.drawImage(src, Math.sin(r * .45 + t * 3) * 6, r * cellH, src.width, cellH, 0, r, cols, 1);\n  const d = sg.getImageData(0, 0, cols, rows).data;\n  let out = '';\n  for (let r = 0; r < rows; r++) {\n    for (let c = 0; c < cols; c++) out += CS[Math.min(9, Math.floor(d[(r * cols + c) * 4 + 3] / 25.6))];\n    out += '\\n';\n  }\n  pre.textContent = out;                  // <pre aria-hidden=\"true\">\n  requestAnimationFrame(() => frame(t + 1 / 60));\n}",
   "css": "<h1 class=\"sr-only\">ASCII</h1>\n<pre class=\"ascii\" aria-hidden=\"true\"></pre>\n.ascii { font: 8px/1 ui-monospace, monospace; letter-spacing: 0;\n  background: linear-gradient(90deg, #22bdd6, #7d64ff);\n  -webkit-background-clip: text; background-clip: text; color: transparent; }"
  },
