   "css": "<div class=\"ring\" aria-label=\"AROUND\"><div class=\"spin\">\n  <span style=\"--i:0\" aria-hidden=\"true\">A</span>…</div></div>\n.ring { perspective: 1000px; }\n.spin { position: relative; transform-style: preserve-3d; animation: spin 6s linear infinite; }\n.spin span { position: absolute; left: 50%; backface-visibility: visible;\n  transform: rotateY(calc(var(--i) * 360deg / var(--n))) translateZ(120px); }\n@keyframes spin { to { transform: rotateY(-360deg); } }\n@media (prefers-reduced-motion: reduce) { .spin { animation: none; } }",
   "canvas": "// troika-three-text(WebGL)라면 곡면에 직접 넣을 수 있다\nimport { Text } from 'troika-three-text';\nconst label = new Text();\nlabel.text = 'AROUND • AROUND • ';\nlabel.fontSize = .3; label.curveRadius = -1.2;   // 음수 = 바깥쪽으로 볼록\nlabel.glyphGeometryDetail = 8; label.anchorX = 'center';\nscene.add(label); label.sync();\nrenderer.setAnimationLoop(t => { label.rotation.y = t / 1000; renderer.render(scene, camera); });"
