  "recipes": {
   "canvas": "// 한 글자씩 <span>(부모에 aria-label, 자식은 aria-hidden). rAF로 커서 추적\nconst spans = [...document.querySelectorAll('.pressure span')];\nlet mx = 0, cx = 0;\naddEventListener('pointermove', e => { mx = e.clientX; });\n(function loop() {\n  cx += (mx - cx) / 15;                                   // 커서를 부드럽게 추적\n  const maxD = innerWidth / 3;\n  for (const s of spans) {\n    const r = s.getBoundingClientRect(), d = Math.abs(cx - (r.left + r.width / 2));\n    const k = Math.max(0, 1 - d / maxD);\n    s.style.fontVariationSettings = `'wght' ${100 + 800 * k}, 'wdth' ${5 + 195 * k}`;\n  }\n  requestAnimationFrame(loop);\n})();",
   "css": ".pressure { font-family: 'Roboto Flex', sans-serif; display: flex; justify-content: space-between; }\n.pressure span { transition: font-variation-settings .1s linear; }\n@media (prefers-reduced-motion: reduce) { .pressure span { font-variation-settings: 'wght' 600, 'wdth' 100 !important; } }"
  },
