  "recipes": {
   "css": "/* 가까울수록 굵게: :has()로 호버 글자 양옆도 중간 굵기로 */\n.c { font-variation-settings: 'wght' 400; transition: font-variation-settings .3s; }\n.c:hover { font-variation-settings: 'wght' 900; }\n.c:has(+ .c:hover), .c:hover + .c { font-variation-settings: 'wght' 600; }\n@media (prefers-reduced-motion: reduce) { .c { transition: none; } }",
   "canvas": "// <h1 aria-label=\"가까워지면 굵게\"><span aria-hidden=\"true\">가</span>…</h1>\nconst letters = [...document.querySelectorAll('.prox span')], R = 80;\naddEventListener('pointermove', e => {\n  for (const el of letters) {\n    const r = el.getBoundingClientRect();\n    const d = Math.hypot(e.clientX - (r.left + r.width / 2), e.clientY - (r.top + r.height / 2));\n    const k = Math.exp(-2.5 * (d / R) ** 2);              // 가우스 감쇠\n    el.style.fontVariationSettings = `'wght' ${400 + 500 * k}, 'opsz' ${9 + 31 * k}`;\n  }\n});"
  },
