   "motion": "import { animate } from 'motion';\n// chars는 aria-hidden의 <span>。부모에 aria-label로 전문을 갖게 한다\ndocument.addEventListener('pointermove', e => {\n  chars.forEach(el => {\n    const r = el.getBoundingClientRect();\n    const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);\n    const d = Math.hypot(dx, dy), k = d < 120 ? (1 - d / 120) * 0.4 : 0;\n    animate(el, { x: dx * k, y: dy * k }, { type: 'spring', stiffness: 300, damping: 24 });\n  });\n});\nif (matchMedia('(prefers-reduced-motion: reduce)').matches) { /* 리스너를 붙이지 않는다 */ }"
