  "recipes": {
   "canvas": "// 매 프레임: 목표 오프셋을 계산하고 현재값을 15%씩 끌어당긴다\nconst R = 120, MAX = 30;\nfunction tick() {\n  for (const c of chars) {           // c = { hx, hy, x, y }(hx,hy는 원래 중심)\n    const dx = c.hx - mouse.x, dy = c.hy - mouse.y, d = Math.hypot(dx, dy) || 1;\n    const k = d < R ? (1 - d / R) * MAX : 0;\n    c.x += (dx / d * k - c.x) * 0.15;\n    c.y += (dy / d * k - c.y) * 0.15;\n    ctx.fillText(c.ch, c.hx + c.x, c.hy + c.y);\n  }\n  requestAnimationFrame(tick);\n}",
   "gsap": "const split = SplitText.create('.repel', { type: 'chars' });\nconst homes = split.chars.map(el => { const b = el.getBoundingClientRect(); return { el, cx: b.left + b.width / 2, cy: b.top + b.height / 2, ox: 0, oy: 0 }; });\nconst mouse = { x: -1e4, y: -1e4 };\naddEventListener('pointermove', e => { mouse.x = e.clientX; mouse.y = e.clientY; });\ngsap.ticker.add(() => homes.forEach(h => {\n  const dx = h.cx - mouse.x, dy = h.cy - mouse.y, d = Math.hypot(dx, dy) || 1;\n  const k = d < 120 ? (1 - d / 120) * 30 : 0;\n  h.ox += (dx / d * k - h.ox) * 0.15; h.oy += (dy / d * k - h.oy) * 0.15;\n  gsap.set(h.el, { x: h.ox, y: h.oy });\n}));",
   "css": "/* JS에서 각 글자에 --x / --y를 쓰고 CSS 쪽은 표시만 담당 */\n.repel .char { display: inline-block; translate: var(--x, 0) var(--y, 0); }\n@media (prefers-reduced-motion: reduce) { .repel .char { translate: none; } }"
  },
