  "recipes": {
   "css": "/* <a class=\"roll\" aria-label=\"자세히 보기\"><span class=\"ch\" data-ch=\"상\" style=\"--i:0\" aria-hidden=\"true\"><span>상</span></span>…</a> */\n.roll .ch { position: relative; display: inline-block; overflow: hidden; vertical-align: top; }\n.roll .ch span, .roll .ch::after { display: block; transition: translate .4s cubic-bezier(.33,1,.68,1);\n  transition-delay: calc(var(--i) * 20ms); }\n.roll .ch::after { content: attr(data-ch); position: absolute; inset: 100% 0 auto; color: var(--accent); }\n.roll:hover .ch span, .roll:hover .ch::after { translate: 0 -100%; }\n@media (prefers-reduced-motion: reduce) { .roll .ch span, .roll .ch::after { transition: none; } }",
   "motion": "import { animate, stagger } from 'motion';\n// .ch(overflow:hidden) 안에,[원본, 복제] 를 세로로 쌓은 .stack을 하나 넣는다 → 절반(1행분) 올린다\nconst stacks = btn.querySelectorAll('.ch > .stack');\nbtn.addEventListener('pointerenter', () => animate(stacks, { y: '-50%' }, { duration: .4, ease: [.33, 1, .68, 1], delay: stagger(.02) }));\nbtn.addEventListener('pointerleave', () => animate(stacks, { y: '0%' }, { duration: .4, ease: [.33, 1, .68, 1], delay: stagger(.02) }));",
   "waapi": "// 같은 .stack 구조로 Web Animations API만으로 쓴다\nconst stacks = [...btn.querySelectorAll('.ch > .stack')];\nconst roll = up => stacks.forEach((el, i) => el.animate({ translate: up ? '0 -50%' : '0 0' },\n  { duration: 400, delay: i * 20, easing: 'cubic-bezier(.33,1,.68,1)', fill: 'forwards' }));   // 현재값에서 보간\nbtn.addEventListener('pointerenter', () => roll(true));\nbtn.addEventListener('pointerleave', () => roll(false));"
  },
