  "recipes": {
   "motion": "import { animate } from 'motion';\nlet last = null; const items = [];\naddEventListener('pointermove', e => {\n  if (last && Math.hypot(e.clientX - last.x, e.clientY - last.y) < 88) return;\n  const ang = last ? Math.atan2(e.clientY - last.y, e.clientX - last.x) * 180 / Math.PI : 0;\n  last = { x: e.clientX, y: e.clientY };\n  const el = Object.assign(document.createElement('span'), { className: 'stamp', textContent: '✨' });\n  el.setAttribute('aria-hidden', 'true');\n  el.style.cssText = `left:${e.clientX}px;top:${e.clientY}px;rotate:${ang}deg`;\n  document.body.append(el); items.push(el);\n  animate(el, { scale: [0.5, 1], y: [0, -12] }, { type: 'spring', stiffness: 300 });\n  if (items.length > 7) remove(items.shift());\n});\nconst remove = el => animate(el, { opacity: 0, scale: 0.5 }, { duration: .5 }).then(() => el.remove());\n// 정지하면 30ms마다 오래된 것부터 remove(items.shift())",
   "css": ".stamp { position: fixed; pointer-events: none; translate: -50% -50%; font-weight: 800; }\n@media (prefers-reduced-motion: reduce) { .stamp { display: none; } }"
  },
