   "css": ".reveal { position: relative; --x: 0%; }\n.reveal .back { position: absolute; inset: 0; clip-path: inset(0 calc(100% - var(--x)) 0 0); }\n.reveal:not(:hover) .back { transition: clip-path .4s cubic-bezier(.33,1,.68,1); }\n@media (prefers-reduced-motion: reduce) { .reveal .back { transition: none; } }\n/* JS */\ncard.addEventListener('pointermove', e => { const r = card.getBoundingClientRect();\n  card.style.setProperty('--x', ((e.clientX - r.left) / r.width * 100) + '%'); });\ncard.addEventListener('pointerleave', () => card.style.setProperty('--x', '0%'));",
   "motion": "import { motion, useMotionValue, useSpring, useTransform } from 'motion/react';\nconst x = useMotionValue(0), sx = useSpring(x, { stiffness: 300, damping: 30 });\nconst clip = useTransform(sx, v => `inset(0 ${100 - v}% 0 0)`);\n<div onPointerMove={e => { const r = e.currentTarget.getBoundingClientRect(); x.set((e.clientX - r.left) / r.width * 100); }}\n     onPointerLeave={() => x.set(0)}>\n  <p>{front}</p>\n  <motion.p aria-hidden style={{ clipPath: clip, position: 'absolute', inset: 0 }}>{back}</motion.p>\n</div>"
