  "recipes": {
   "canvas": "// GLSL(Three.js ShaderMaterial의 vertexShader)\nuniform vec3 uDisplacement;           // Raycaster로 구한 커서의 월드 좌표\nvarying vec2 vUv;\nfloat easeInOutCubic(float x) { return x < .5 ? 4. * x * x * x : 1. - pow(-2. * x + 2., 3.) / 2.; }\nfloat map(float v, float a, float b, float c, float d) { return c + (d - c) * (v - a) / (b - a); }\nvoid main() {\n  vUv = uv;\n  vec4 wp = modelMatrix * vec4(position, 1.0);\n  float d = length(uDisplacement - wp.xyz);\n  float v = easeInOutCubic(clamp(map(d, 0., 3., 1., 0.), 0., 1.));\n  vec3 p = position; p.z += v * 1.0;       // 부풀림\n  gl_Position = projectionMatrix * viewMatrix * modelMatrix * vec4(p, 1.0);\n}\n// geometry = new THREE.PlaneGeometry(15, 15, 100, 100); 글자는 CanvasTexture로 붙인다",
   "css": "/* 간이판: 확대 렌즈만(왜곡 없음). --x/--y를 포인터로 갱신 */\n.lens { position: relative; }\n.lens::after { content: attr(data-text); position: absolute; inset: 0; scale: 1.6;\n  transform-origin: var(--x) var(--y); clip-path: circle(48px at var(--x) var(--y)); pointer-events: none; }\n@media (prefers-reduced-motion: reduce) { .lens::after { display: none; } }"
  },
