  "recipes": {
   "waapi": "function update(el, next, prev) {\n  const up = next > prev, a = fmt(prev), b = fmt(next);\n  el.innerHTML = [...b].map((c, i) => `<span class=\"d\">${c}</span>`).join('');\n  [...el.children].forEach((d, i) => {\n    if (a[a.length - b.length + i] === d.textContent) return;          // 바뀐 자리수만\n    d.animate([{ transform: `translateY(${up ? .3 : -.3}em)`, opacity: 0 }, { transform: 'none', opacity: 1 }],\n      { duration: 350, easing: 'cubic-bezier(.33,1,.68,1)' });\n  });\n  el.animate([{ backgroundColor: up ? 'rgb(53 200 146 / .35)' : 'rgb(255 114 94 / .35)' }, { backgroundColor: 'transparent' }],\n    { duration: 600, easing: 'ease-out' });\n}",
   "css": ".price { font-variant-numeric: tabular-nums; border-radius: 6px; }\n.price .d { display: inline-block; }\n.price[data-trend=\"up\"]::after { content: \" ▲\"; color: #35c892; }\n.price[data-trend=\"down\"]::after { content: \" ▼\"; color: #ff725e; }\n@media (prefers-reduced-motion: reduce) { .price .d { animation: none !important; } }",
   "motion": "import { animate } from 'motion';\nanimate(changedDigits, { y: [up ? '0.3em' : '-0.3em', 0], opacity: [0, 1] }, { duration: .35, ease: 'easeOut' });\nanimate(el, { backgroundColor: [up ? '#35c89255' : '#ff725e55', 'rgba(0,0,0,0)'] }, { duration: .6 });"
  },
