   "gsap": "const accent = getComputedStyle(cell).getPropertyValue('--accent');   // var()는 보간할 수 없으므로 실제 색을 읽는다\nconst tl = gsap.timeline();\ntl.to(cell.querySelector('.n'), { rotationX: -90, duration: .175, ease: 'power1.in',\n    onComplete: () => cell.querySelector('.n').textContent = next })\n  .to(cell.querySelector('.n'), { rotationX: 0, duration: .175, ease: 'power1.out' })\n  // 150ms마다 켜기·끄기·켜기·끄기(set은 시간 0의 전환)\n  .set(cell, { backgroundColor: accent }).set(cell, { backgroundColor: 'transparent' }, '+=.15')\n  .set(cell, { backgroundColor: accent }, '+=.15').set(cell, { backgroundColor: 'transparent' }, '+=.15');\nlive.textContent = `홈 ${next}점`;   // aria-live=\"polite\"",
