  "recipes": {
   "gsap": "// 각 단어의 사각형을 재서 필의 x / width로 옮긴다\nconst pill = document.querySelector('.pill');\nfunction go(word) {\n  const r = word.getBoundingClientRect(), p = word.parentElement.getBoundingClientRect();\n  gsap.to(pill, { x: r.left - p.left - 8, width: r.width + 16, duration: .1, ease: 'power2.out' });\n  words.forEach(w => w.classList.toggle('on', w === word)); // .on { color: #0d1320 }\n}",
   "css": ".line { position: relative; }\n.pill { position: absolute; inset-block: -.1em; left: 0; width: 0; border-radius: 999px; background: var(--accent); z-index: -1;\n  transition: translate .1s cubic-bezier(.33,1,.68,1), width .1s cubic-bezier(.33,1,.68,1); }\n.word.on { color: #0d1320; transition: color .1s; }\n@media (prefers-reduced-motion: reduce) { .pill { transition: none; } }",
   "remotion": "// 현재 단어의 사각형(미리 measureText로 계산)으로 보간\nconst k = tokens.findIndex(tk => tk.fromMs <= ms && ms < tk.toMs);\nconst p = interpolate(ms - tokens[k].fromMs, [0, 100], [0, 1], { extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });\nconst prev = rects[Math.max(0, k - 1)], cur = rects[k];\nconst left = interpolate(p, [0, 1], [prev.x, cur.x]), width = interpolate(p, [0, 1], [prev.w, cur.w]);"
  },
