  "valuesEn": [
   "300 wpm → 200ms per word",
   "+50–100% on punctuation / long words",
   "ORP ≈ 35% into the word",
   "585 vs 316 wpm (study)"
  ],
  "recipes": {
   "canvas": "// ORP 글자의 중심을 항상 cx에 둔다\nconst orp = w => Math.min(w.length - 1, Math.floor(w.length * .35));\nfunction drawWord(ctx, w, cx, cy) {\n  const i = orp(w), ow = ctx.measureText(w[i]).width;\n  ctx.textAlign = 'right'; ctx.fillStyle = '#fff'; ctx.fillText(w.slice(0, i), cx - ow / 2, cy);\n  ctx.textAlign = 'left'; ctx.fillText(w.slice(i + 1), cx + ow / 2, cy);\n  ctx.textAlign = 'center'; ctx.fillStyle = accent; ctx.fillText(w[i], cx, cy);\n}\nconst delay = w => 60000 / wpm * (/[.,!?]$/.test(w) || w.length > 8 ? 1.5 : 1);",
   "css": "/* 3개의 span(앞·ORP·뒤)을 grid로 중앙 열에 맞춘다 */\n.rsvp { display: grid; grid-template-columns: 1fr auto 1fr; font: 700 2rem/1 sans-serif; }\n.rsvp .pre { text-align: right; } .rsvp .orp { color: var(--accent); } .rsvp .post { text-align: left; }\n/* 읽기용으로 전문을 별도 준비하고 .rsvp는 aria-hidden=\"true\" */",
   "remotion": "const { fps } = useVideoConfig(); const frame = useCurrentFrame();\nconst per = Math.round(fps * 60 / 300); // 300 wpm\nconst w = words[Math.min(words.length - 1, Math.floor(frame / per))];\nconst i = Math.min(w.length - 1, Math.floor(w.length * .35));\nreturn <div className=\"rsvp\"><span className=\"pre\">{w.slice(0, i)}</span><span className=\"orp\">{w[i]}</span><span className=\"post\">{w.slice(i + 1)}</span></div>;"
  },
