  "curve": "standard",
  "trigger": "시간·상태 변화",
  "triggerEn": "Time or state change",
  "tech": [
   "WAAPI",
   "GSAP",
   "Motion"
  ],
  "cost": "가벼움",
  "costEn": "Light",
  "inputs": [
   "자동"
  ],
  "inputsEn": [
   "Automatic"
  ],
  "reduced": "동작을 멈추고 글자가 읽히는 대표 컷을 표시합니다.",
  "reducedEn": "Stop the motion and show a representative frame where the text is readable.",
  "accent": "cyan",
