  "recipe": "text-wrap: balance / balance ≤ 6행 / 리사이즈 debounce ≈ 150ms / SplitText autoSplit",
  "recipeEn": "text-wrap: balance / balance ≤ 6 lines / resize debounce ≈ 150ms / SplitText autoSplit",
