   "waapi": "// 미대응 환경: scrollHeight를 재서 px로 보간 → 끝나면 auto로 되돌린다\nbtn.onclick = () => {\n  const from = box.offsetHeight; box.classList.add('open');\n  const to = box.scrollHeight;\n  box.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: 450, easing: 'ease' });\n  btn.setAttribute('aria-expanded', 'true');\n};",
   "motion": "<motion.div initial={false} animate={{ height: open ? 'auto' : '1.5em' }} transition={{ duration: .45, ease: 'easeInOut' }} style={{ overflow: 'hidden' }}>\n  <p style={open ? {} : { display: '-webkit-box', WebkitLineClamp: 1, WebkitBoxOrient: 'vertical' }}>{text}</p>\n</motion.div>\n<button aria-expanded={open} onClick={() => setOpen(!open)}>{open ? '닫기' : '더 읽기'}</button>"
