   "motion": "import { animate } from 'motion';\n// 10개의 <svg class=\"star\" aria-hidden=\"true\"> 를 글자 위에 absolute로 놓는다\ndocument.querySelectorAll('.star').forEach(async star => {\n  while (true) {   // 한 번 빛날 때마다 다른 곳에서 다시 태어난다\n    star.style.left = Math.random() * 100 + '%'; star.style.top = Math.random() * 100 + '%';\n    await animate(star, { opacity: [0, 1, 0], scale: [0, 1, 0], rotate: [75, 120, 150] },\n      { duration: 0.8, delay: Math.random() * 2 });\n  }\n});",
