   "css": ".star { position:absolute; width:1em; animation: twinkle .8s ease-in-out infinite; }\n@keyframes twinkle { 0%,100% { opacity:0; transform:scale(0) rotate(75deg); }\n  50% { opacity:1; transform:scale(1) rotate(120deg); } }\n@media (prefers-reduced-motion: reduce) { .star { animation:none; opacity:.8; } }"
