  "recipes": {
   "css": ".danmaku { position:absolute; inset:0; overflow:hidden; pointer-events:none; }\n.c { position:absolute; left:100%; white-space:nowrap; color:#fff; font-weight:700;\n  -webkit-text-stroke: 3px rgb(0 0 0 / .6); paint-order: stroke fill;\n  top: calc(var(--lane) * 1.6em);\n  animation: fly 3.5s linear forwards; }\n/* 자기 폭만큼도 함께 이동: 컨테이너 폭 + 자신의 폭 */\n@keyframes fly { to { transform: translateX(calc(-100cqw - 100%)); } }\n.danmaku { container-type: inline-size; }",
   "canvas": "// 레인별로 「마지막 댓글 오른쪽 끝이 화면에 다 들어오는 시각」을 기억해 둔다\nfunction spawn(text, now) {\n  const w = ctx.measureText(text).width, speed = (W + w) / 3.5;\n  let lane = lanes.findIndex(l => l.freeAt <= now); if (lane < 0) lane = 0;   // 빈 곳이 없으면 맨 위\n  lanes[lane].freeAt = now + w / speed + 0.3;             // 오른쪽 끝이 다 나올 때까지 사용하지 않는다\n  comments.push({ text, w, lane, t0: now, speed });\n}\ncomments.forEach(c => { const x = W - (now - c.t0) * c.speed;\n  ctx.strokeText(c.text, x, laneY(c.lane)); ctx.fillText(c.text, x, laneY(c.lane)); });",
   "remotion": "// comments: [{ text, from, lane }]\nreturn comments.map((c, i) => {\n  const x = interpolate(frame, [c.from, c.from + 3.5 * fps], [width, -c.w], { extrapolateRight: 'clamp' });\n  return <div key={i} style={{ position: 'absolute', top: c.lane * 40, transform: `translateX(${x}px)`,\n    color: 'white', WebkitTextStroke: '3px rgba(0,0,0,.6)', paintOrder: 'stroke fill' }}>{c.text}</div>; });"
  },
