  "recipes": {
   "remotion": "// 글자 수에서 표시 프레임을 정한다(전각 1 / 반각 0.5, 최단 0.5초)\nconst count = s => [...s].reduce((a, c) => a + (/[\\x20-\\x7e]/.test(c) ? .5 : 1), 0);\nlet from = 0;\nreturn cues.map((c, i) => { const len = Math.max(.5, count(c) / 7) * fps;\n  const el = <Sequence key={i} from={from} durationInFrames={Math.round(len)}><Subtitle text={c} /></Sequence>;\n  from += Math.round(len) + 3; return el; });",
   "css": "/* WebVTT 자막을 ::cue로 다듬는다(움직임은 넣지 않음) */\nvideo::cue { font-family: \"Pretendard\", sans-serif; font-size: 4.2cqh; color: #fff;\n  background: transparent; text-shadow: 0 0 3px #000, 0 0 3px #000; }\n/* 자막 텍스트는 문장부호를 자제하고 호흡 단위로 끊어 둔다 */",
   "waapi": "// VTT 만들기: 표시 초 = 글자 수 / 4\nconst toVTT = cues => 'WEBVTT\\n\\n' + cues.map((c, i, a) => {\n  const s = a.slice(0, i).reduce((t, x) => t + Math.max(.5, count(x) / 7) + .12, 0), e = s + Math.max(.5, count(c) / 7);\n  const ts = v => new Date(v * 1000).toISOString().slice(11, 23);\n  return `${ts(s)} --> ${ts(e)}\\n${c}`; }).join('\\n\\n');"
  },
