   "css": "/* .stage는 검은 배경. 카드의 드나듦만 animation으로 */\n.card { opacity: 0; animation: card 4s ease-in-out forwards; }\n@keyframes card { 0% { opacity: 0 } 12.5% { opacity: 1 } 87.5% { opacity: 1 } 100% { opacity: 0 } }\n/* 0.5s in / 3s hold / 0.5s out */\n@media (prefers-reduced-motion: reduce) { .card { animation-timing-function: steps(1, end); } }",
   "gsap": "const words = card.textContent.trim().split(/\\s+/).length;\nconst hold = Math.max(1.5, words * .6) * 2;\ngsap.timeline()\n  .to(scene, { autoAlpha: 0, duration: .5 })\n  .fromTo(card, { autoAlpha: 0 }, { autoAlpha: 1, duration: .5, ease: 'sine.inOut' })\n  .to(card, { autoAlpha: 0, duration: .5, ease: 'sine.inOut' }, '+=' + hold);",
