   "gsap": "gsap.timeline()\n  .from('.lt-name', { scaleX: 0, transformOrigin: 'left', duration: .4, ease: 'expo.out' })\n  .from('.lt-name span', { x: -18, autoAlpha: 0, duration: .4, ease: 'expo.out' }, '<.1')\n  .from('.lt-role', { scaleX: 0, transformOrigin: 'left', duration: .4, ease: 'expo.out' }, '<.07')\n  .to('.lt', { autoAlpha: 0, duration: .3, ease: 'power2.in' }, '+=5');",
