  "tipsEn": [],
  "recipe": "2~4px/컷 @60fps / 120~240px/s / linear / 복제해 루프",
  "recipeEn": "2–4 px per frame @60 fps / 120–240 px/s / linear / duplicate content to loop",
  "curve": "standard",
